sys_script.script:
// Auto-assigns the responsible department based on the complaint category.
(function autoAssignDepartment() {
    var category = current.getValue('category');

    // Only auto-assign if department is not already set
    if (current.getValue('department')) {
        return;
    }

    var department = 'general';

    switch (category) {
        case 'pothole':
            department = 'public_works';
            break;
        case 'traffic':
            department = 'transportation';
            break;
        case 'noise':
        case 'graffiti':
            department = 'police';
            break;
        case 'water_leak':
        case 'sewage':
            department = 'utilities';
            break;
        case 'streetlight':
            department = 'public_works';
            break;
        case 'trash':
            department = 'sanitation';
            break;
        case 'park_damage':
            department = 'parks';
            break;
        default:
            department = 'general';
            break;
    }

    current.setValue('department', department);
})();
